ما ناتج تنفيذ البرنامج الآتي؟
n = 0
if n > 0:
    print("Positive")
elif n < 0:
    print("Negative")
else:
    print("Zero")

ما ناتج تنفيذ برنامج تصنيف استهلاك الكهرباء الآتي؟
units = 250
if units <= 200:
    print("Low")
elif units <= 400:
    print("Medium")
else:
    print("High")

في البرنامج الآتي، أيُّ قيم x تجعل الناتج B؟
if x >= 90:
    print("A")
elif x >= 75:
    print("B")
else:
    print("C")
